import{_ as i,a8 as a,o as l,c as p,ah as r,K as n}from"./chunks/framework.CgKDWdj8.js";import"./chunks/theme.CCmhGRzB.js";const u=JSON.parse('{"title":"OpenClaw ACP——多 Agent 协作","description":"ACP（Agent Control Plane）——OpenClaw 多 Agent 协调器，管理子 Agent 生命周期、会话状态、消息传递与权限控制","frontmatter":{"abstract":"OpenClaw 的 ACP 多 Agent 协调器，讲解其管理子 Agent 生命周期、会话状态与消息传递的机制及 Runtime Handle 缓存等关键设计。","type":"concept","tags":["AI","OpenClaw","ACP","多Agent","协作"],"domain":"AI","description":"ACP（Agent Control Plane）——OpenClaw 多 Agent 协调器，管理子 Agent 生命周期、会话状态、消息传递与权限控制","created":"2026-09-07T00:00:00.000Z","updated":"2026-09-07T00:00:00.000Z","status":"integrated","source":"[[Resources/OpenClaw/核心组件/07-ACP]]","related":["[[🦀 OpenClaw-MOC]]","[[OpenClaw-Agent-Engine]]","[[OpenClaw-Session-Manager]]","[[OpenClaw-Context-Engine]]"],"category":["🦀 OpenClaw","专题分析"]},"headers":[],"relativePath":"vault/Knowledge/AI/OpenClaw-ACP.md","filePath":"vault/Knowledge/AI/OpenClaw-ACP.md","lastUpdated":1790655645000}'),o={name:"vault/Knowledge/AI/OpenClaw-ACP.md"};function d(c,s,h,g,k,A){const e=a("NolebaseGitContributors"),t=a("NolebaseGitChangelog");return l(),p("div",null,[s[0]||(s[0]=r(`<h1 id="openclaw-acp——多-agent-协作" tabindex="-1">OpenClaw ACP——多 Agent 协作 <a class="header-anchor" href="#openclaw-acp——多-agent-协作" aria-label="Permalink to “OpenClaw ACP——多 Agent 协作”">​</a></h1><blockquote><p>ACP（Agent Control Plane）是 OpenClaw 的多 Agent 协调器，负责管理子 Agent 的生命周期、会话状态和消息传递。</p></blockquote><h2 id="解决的问题" tabindex="-1">解决的问题 <a class="header-anchor" href="#解决的问题" aria-label="Permalink to “解决的问题”">​</a></h2><p>单个 Agent 能力有限，复杂任务需要多 Agent 协作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>用户：「帮我分析这段代码的性能问题，然后写一个优化方案」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>主 Agent（代码分析）</span></span>
<span class="line"><span>  → 调用子 Agent A（性能分析专家）</span></span>
<span class="line"><span>  → 调用子 Agent B（优化方案专家）</span></span>
<span class="line"><span>  → 汇总结果，回复用户</span></span></code></pre></div><p>ACP 管理四大职责：</p><ol><li>子 Agent 的启动/关闭</li><li>子 Agent 的会话状态</li><li>父子 Agent 之间的消息传递</li><li>子 Agent 的权限控制（工具/文件访问）</li></ol><h2 id="核心概念-acp-session" tabindex="-1">核心概念：ACP Session <a class="header-anchor" href="#核心概念-acp-session" aria-label="Permalink to “核心概念：ACP Session”">​</a></h2><p>一个 ACP Session 代表一次多 Agent 协作任务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>主 Agent 启动子 Agent</span></span>
<span class="line"><span>  → 创建 ACP Session</span></span>
<span class="line"><span>  → sessionKey = &quot;acp:parent-session:child-agent-id&quot;</span></span>
<span class="line"><span>  → 分配 runtime handle（子 Agent 执行环境）</span></span></code></pre></div><p>每个 ACP Session 独立拥有：</p><ul><li>会话历史（子 Agent 自己的对话记录）</li><li>工具权限（可能与主 Agent 不同）</li><li>模型配置（可以使用不同模型）</li></ul><h2 id="核心流程" tabindex="-1">核心流程 <a class="header-anchor" href="#核心流程" aria-label="Permalink to “核心流程”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>主 Agent 需要调用子 Agent</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>AcpSessionManager</span></span>
<span class="line"><span>  1. initializeSession()</span></span>
<span class="line"><span>     → 创建 ACP session 元数据</span></span>
<span class="line"><span>     → 分配 runtime handle</span></span>
<span class="line"><span>     → 记录到 session 文件</span></span>
<span class="line"><span>  2. 子 Agent 开始工作</span></span>
<span class="line"><span>     → 通过 runtime handle 和主 Agent 通信</span></span>
<span class="line"><span>     → 可以调用工具、读取记忆、访问文件</span></span>
<span class="line"><span>  3. turn 执行（每轮对话）</span></span>
<span class="line"><span>     → runManagerTurn()</span></span>
<span class="line"><span>     → 把消息发给子 Agent → 拿到回复</span></span>
<span class="line"><span>  4. 关闭 session</span></span>
<span class="line"><span>     → closeSession()</span></span>
<span class="line"><span>     → 释放 runtime handle</span></span>
<span class="line"><span>     → 保存会话历史到文件</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>主 Agent 拿到子 Agent 的结果，继续工作</span></span></code></pre></div><h2 id="关键设计" tabindex="-1">关键设计 <a class="header-anchor" href="#关键设计" aria-label="Permalink to “关键设计”">​</a></h2><h3 id="_1-runtime-handle-缓存" tabindex="-1">1. Runtime Handle 缓存 <a class="header-anchor" href="#_1-runtime-handle-缓存" aria-label="Permalink to “1. Runtime Handle 缓存”">​</a></h3><p>子 Agent 的执行环境（runtime handle）被缓存：</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#E5C07B;"> ManagerRuntimeHandleCache</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">  private</span><span style="--shiki-light:#E36209;--shiki-dark:#E06C75;"> handles</span><span style="--shiki-light:#D73A49;--shiki-dark:#56B6C2;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;"> Map</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#E5C07B;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#E5C07B;">AcpRuntimeHandle</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">&gt;();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">}</span></span></code></pre></div><p>同一子 Agent 被多次调用时复用已有 handle，避免重复启动开销。</p><h3 id="_2-会话身份协调-identity-reconciliation" tabindex="-1">2. 会话身份协调（Identity Reconciliation） <a class="header-anchor" href="#_2-会话身份协调-identity-reconciliation" aria-label="Permalink to “2. 会话身份协调（Identity Reconciliation）”">​</a></h3><p>系统重启后需要将磁盘 session 文件与内存 runtime handle 对齐：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>系统重启</span></span>
<span class="line"><span>  → 扫描所有 session 文件，找到有 ACP 元数据的</span></span>
<span class="line"><span>  → 对每个 session，检查 runtime handle 是否还活着</span></span>
<span class="line"><span>  → 如果死了，清理元数据（避免僵尸 session）</span></span></code></pre></div><h3 id="_3-按会话排队的-actor-模型" tabindex="-1">3. 按会话排队的 Actor 模型 <a class="header-anchor" href="#_3-按会话排队的-actor-模型" aria-label="Permalink to “3. 按会话排队的 Actor 模型”">​</a></h3><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#E5C07B;"> SessionActorQueue</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">  // 每个 session 有自己的队列</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">  // 保证：同一个 session 的消息按顺序处理</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">}</span></span></code></pre></div><p>防止同一子 Agent 同时处理多条消息导致状态混乱。</p><h2 id="关键源码文件" tabindex="-1">关键源码文件 <a class="header-anchor" href="#关键源码文件" aria-label="Permalink to “关键源码文件”">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>src/acp/control-plane/manager.core.ts</code></td><td>ACP 管理器核心（<code>AcpSessionManager</code>）</td></tr><tr><td><code>src/acp/control-plane/manager.initialize-session.ts</code></td><td>初始化 session</td></tr><tr><td><code>src/acp/control-plane/manager.turn-runner.ts</code></td><td>执行一轮对话（turn）</td></tr><tr><td><code>src/acp/control-plane/manager.close-session.ts</code></td><td>关闭 session</td></tr><tr><td><code>src/acp/control-plane/manager.runtime-handle-ensure.ts</code></td><td>确保 runtime handle 可用</td></tr><tr><td><code>src/acp/translator.ts</code></td><td>主 Agent 和子 Agent 之间的消息翻译器</td></tr><tr><td><code>src/acp/types.ts</code></td><td>ACP 核心类型定义</td></tr></tbody></table><h2 id="acp-与-agentcommand-的关系" tabindex="-1">ACP 与 AgentCommand 的关系 <a class="header-anchor" href="#acp-与-agentcommand-的关系" aria-label="Permalink to “ACP 与 AgentCommand 的关系”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>AgentCommand</th><th>ACP</th></tr></thead><tbody><tr><td>职责</td><td>编排「一次 AI 调用」</td><td>管理「多个 Agent 的协作」</td></tr><tr><td>粒度</td><td>细粒度（一次模型调用 + 工具调用）</td><td>粗粒度（整个子 Agent 的生命周期）</td></tr><tr><td>调用关系</td><td>ACP 内部会调用 AgentCommand</td><td>AgentCommand 不会调用 ACP</td></tr></tbody></table><p>ACP 是「管理者」，AgentCommand 是「干活的人」。</p><h2 id="设计亮点" tabindex="-1">设计亮点 <a class="header-anchor" href="#设计亮点" aria-label="Permalink to “设计亮点”">​</a></h2><p><strong>1. 可观测性</strong>：<code>AcpSessionManager.getObservabilitySnapshot()</code> 返回活跃 session 数量、每个 session 的 runtime handle 状态、历史 turn 延迟统计。</p><p><strong>2. 错误分类</strong>：</p><ul><li><code>session-not-found</code> → session 已关闭</li><li><code>runtime-handle-lost</code> → 需要重新创建 handle</li><li><code>turn-timeout</code> → 需要重试</li></ul><p><strong>3. 父流设置（Parent Stream）</strong>：子 Agent 的生成过程可以实时流式返回给主 Agent，无需等待全部完成。</p><h2 id="源码阅读路线" tabindex="-1">源码阅读路线 <a class="header-anchor" href="#源码阅读路线" aria-label="Permalink to “源码阅读路线”">​</a></h2><ol><li><code>src/acp/types.ts</code> — 理解核心类型（最短文件）</li><li><code>src/acp/control-plane/manager.core.ts</code> 前 150 行 — 理解 <code>AcpSessionManager</code> 类结构</li><li><code>src/acp/translator.ts</code> 前 100 行 — 理解主 Agent 和子 Agent 通信机制</li></ol>`,37)),n(e),n(t)])}const m=i(o,[["render",d]]);export{u as __pageData,m as default};
